    }

    @Test
    void rejectsCompanyReservationWithOnlyCnpj() throws Exception {
        String onlyCnpjJson = """
                {"roomNumber": 101, "guestName": "Test", "guestEmail": "test@example.com",
                 "companyCnpj": "12.345.678/0001-90", "checkIn": "2027-05-10", "checkOut": "2027-05-12",
                 "guests": 1, "ratePlan": "STANDARD"}
                """;
        HttpResponse<String> response = post("/reservations", onlyCnpjJson);
        assertEquals(400, response.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
    }

    @Test
    void rejectsForeignerReservationWithOnlyPassport() throws Exception {
        String onlyPassportJson = """
                {"roomNumber": 101, "guestName": "Test", "guestEmail": "test@example.com",
